#include <Arduino.h>
#include <Servo.h>
Servo servo1;
Servo servo2;
Servo servo3;
const int RGB1_R = 2;
const int RGB1_G = 3;
const int RGB1_B = 4;
const int RGB2_R = 5;
const int RGB2_G = 6;
const int RGB2_B = 7;
const int RGB3_R = 8;
const int RGB3_G = 9;
const int RGB3_B = 10;
const int SERVO1_PIN = 11;
const int SERVO2_PIN = 12;
const int SERVO3_PIN = 13;
int currentColorIndex = 0;
const int colorSequence[][3] = {
  {255, 0, 0},   
  {0, 255, 0},   
  {0, 0, 255},   
  {255, 255, 0}, 
  {0, 255, 255}, 
  {255, 0, 255}, 
  {255, 255, 255}
};
const int servoAngles[][3] = {
  {0, 45, 90},   
  {45, 90, 135}, 
  {90, 135, 180},
  {135, 180, 0}, 
  {180, 0, 45},  
  {0, 45, 90},   
  {90, 135, 180} 
};

void setup();
void loop();
void setColor(int r, int g, int b);
void moveServos(int angle1, int angle2, int angle3);
void setup() {
  pinMode(RGB1_R, OUTPUT);
  pinMode(RGB1_G, OUTPUT);
  pinMode(RGB1_B, OUTPUT);
  pinMode(RGB2_R, OUTPUT);
  pinMode(RGB2_G, OUTPUT);
  pinMode(RGB2_B, OUTPUT);
  pinMode(RGB3_R, OUTPUT);
  pinMode(RGB3_G, OUTPUT);
  pinMode(RGB3_B, OUTPUT);
  servo1.attach(SERVO1_PIN);
  servo2.attach(SERVO2_PIN);
  servo3.attach(SERVO3_PIN);
  setColor(0, 0, 0);
  moveServos(0, 0, 0);
}
void loop() {
  setColor(colorSequence[currentColorIndex][0],
           colorSequence[currentColorIndex][1],
           colorSequence[currentColorIndex][2]);
  moveServos(servoAngles[currentColorIndex][0],
             servoAngles[currentColorIndex][1],
             servoAngles[currentColorIndex][2]);
  delay(2000);
  currentColorIndex = (currentColorIndex + 1) % 7;
}
void setColor(int r, int g, int b) {
  analogWrite(RGB1_R, r);
  analogWrite(RGB1_G, g);
  analogWrite(RGB1_B, b);
  analogWrite(RGB2_R, r);
  analogWrite(RGB2_G, g);
  analogWrite(RGB2_B, b);
  analogWrite(RGB3_R, r);
  analogWrite(RGB3_G, g);
  analogWrite(RGB3_B, b);
}
void moveServos(int angle1, int angle2, int angle3) {
  servo1.write(angle1);
  servo2.write(angle2);
  servo3.write(angle3);
}
